f) -> int:\\n54|        return self.up + self.down\\n55|\\n56|\\n57|def run_gh(args: Sequence[str], check: bool = True) -> subprocess.CompletedProcess:\\n58|    \\\"\\\"\\\"Run ``gh`` with the given arguments and return the completed process.\\\"\\\"\\\"\\n59|    return subprocess.run(\\n60|        [\\\"gh\\\", *args],\\n61|        capture_output=True,\\n62|        text=True,\\n63|        check=check,\\n64|        timeout=GH_TIMEOUT_SECONDS,\\n65|    )\\n66|\\n67|\\n68|def fetch_open_prs(repo: str) -> List[Dict[str, Any]]:\\n69|    \\\"\\\"\\\"Return JSON metadata for every open PR in ``repo``.\\\"\\\"\\\"\\n70|    proc = run_gh(\\n71|        [\\n72|            \\\"pr\\\",\\n73|            \\\"list\\\",\\n74|            \\\"--repo\\\",\\n75|            repo,\\n76|            \\\"--state\\\",\\n77|            \\\"open\\\",\\n78|            \\\"--json\\\",\\n79|            \\\"number,title,author,isDraft,createdAt\\\",\\n80|            \\\"--limit\\\",\\n(more lines below)\"}","truncated":false}
